  {
    slug: "weekly-black-fungus",
    title: "凉拌黑木耳",
    date: "2026-10-16",
    tags: ["每周一菜"],
    author: "孟自力",
    summary: "一道几毛钱成本、却对血脂友好的凉菜。关键是：怎么泡、怎么拌，都有讲究。",
    body: `## 为什么推荐它？

黑木耳热量低、富含膳食纤维与"木耳多糖"，传统上被认为有助于血脂管理、改善血液黏稠度。作为蔬菜搭配，它能让一餐更丰富、更"刮油"。不过要记住：它再好，也只是健康饮食的一部分，不能替代药物。

### 食材（2 人份）

- 干黑木耳 10–15 克（泡发后约一小碗）
- 胡萝卜丝、黄瓜丝少许（增色增纤维）
- 蒜末、香醋、少许生抽、一滴香油

### 做法

1. 木耳用<strong>冷水泡发 1–2 小时</strong>（切勿久泡、更忌过夜），洗净撕小朵；
2. 沸水焯 2–3 分钟熟透，过凉沥干；
3. 加蔬菜丝与蒜末，淋香醋、少许生抽、一滴香油拌匀即可——全程控盐控油。

## 护心点评

低油、低盐、高纤维，几乎不增加心血管负担，还能帮着"换换口味"少吃肉。把它作为日常凉菜，性价比极高。

> <strong>安全提醒（重要）：</strong>木耳泡发时间过长（尤其夏季室温过夜）可能滋生"椰毒假单胞菌"，产生米酵菌酸毒素，可致严重食物中毒。请<strong>现泡现吃、冷水短时泡发、泡后及时烹调</strong>，泡发后若有黏腻、异味请丢弃。本文为饮食科普，特殊疾病请遵医嘱。

更多护心食谱与烹饪方式对比，欢迎回到科普主页 [「护心厨房」](../index.html#kitchen) 板块查阅。

延伸阅读 · 权威信息来源`
  },

  {
    slug: "weekly-dish-tofu-tomato",
    title: "番茄炖豆腐：护心又下饭",
    date: "2026-10-16",
    tags: ["每周一菜"],
    author: "孟自力",
    summary: "护心饮食不等于\"清汤寡水\"。这道菜低脂、高钙、富含番茄红素，连小朋友都爱吃——是我常推荐给心血管患者家庭的\"入门护心菜\"。",
    body: `## 为什么说它"护心"？

这道菜的好处，藏在三种食材里：

- <strong>番茄</strong>：富含番茄红素，是一种抗氧化物质，有助于保护血管内皮；熟番茄（加油烹调）里番茄红素反而更易吸收。
- <strong>豆腐</strong>：植物蛋白 + 钙 + 大豆异黄酮，替代部分红肉，能帮着控制血胆固醇。
- <strong>少油少盐的炖法</strong>：没有油炸、没有重盐，正好契合"每日盐 < 5 克、油 25–30 克"的护心原则。

### 食材（2–3 人份）

- 老豆腐 1 块（约 400 克，切小块）
- 熟透的番茄 2 个（约 300 克，去皮切丁）
- 鸡蛋 1 个（可选，增加蛋白质）
- 葱姜少许、番茄酱 1 勺（无添加糖更佳）
- 食用油 1 汤匙、盐约 2 克（全程控盐）

### 做法

1. 热锅放 1 汤匙油，下葱姜爆香，倒入番茄丁中小火炒出红色汤汁（可加 1 勺无糖番茄酱提味）。
2. 加半碗水，放入豆腐块，轻轻推匀，盖盖小火炖 8–10 分钟入味。
3. 淋入打散的蛋液成蛋花，加盐调味，撒葱花出锅。

## 护心点评

整道菜几乎无额外脂肪负担，豆腐提供优质蛋白，番茄带来抗氧化物，口感酸甜开胃、特别适合夏天没胃口或需要控盐控脂的人群。把它当作"红肉替代"的一餐，长期坚持比偶尔吃一顿"护心保健品"实在得多。

> <strong>小提醒：</strong>豆腐含嘌呤中等，痛风急性发作期请遵医嘱适量；肾功能异常者注意蛋白质总量。本文为饮食科普，具体膳食方案请结合个人健康状况。

更多护心食材选择、烹饪方式红黑榜与 20 道家常食谱，欢迎回到科普主页 [「护心厨房」](../index.html#kitchen) 板块系统查看。

延伸阅读 · 权威信息来源`
  },

  {
    slug: "weekly-oats-porridge",
    title: "燕麦杂粮早餐粥",
    date: "2026-10-16",
    tags: ["每周一菜"],
    author: "孟自力",
    summary: "一天之计在于晨。把早餐换成这碗燕麦杂粮粥，是用最便宜的方式，给血管\"减减负\"。",
    body: `## 为什么推荐它？

燕麦里含有一种叫 <strong>β-葡聚糖</strong> 的可溶性膳食纤维，它能在肠道里"绑住"一部分胆固醇、帮助降低"坏胆固醇"（LDL-C）。再搭配糙米、小米等杂粮，替代精白米面，升糖更平稳、饱腹更持久——对血脂、血糖、体重都友好。

### 食材（2 人份）

- 燕麦片（优选原味 rolled oats，非速溶含糖款）50 克
- 糙米 / 小米 / 藜麦 各 20–30 克（提前泡 30 分钟更好煮）
- 牛奶或无糖豆浆 200 毫升（也可用清水）
- 核桃碎 1 小把、蓝莓或苹果丁少许（可选）

### 做法

1. 杂粮先加水煮 15–20 分钟至软烂；
2. 加入燕麦片再煮 3–5 分钟，倒入牛奶/豆浆煮沸即关火；
3. 盛出后撒核桃碎与水果，无需额外加糖。

## 护心点评

整碗几乎无添加糖、低油、富含膳食纤维与不饱和脂肪酸，是替代"油条+白粥+咸菜"这种高油高盐早餐的理想选择。坚持比偶尔吃一次更重要——把它变成家庭的固定早餐，长期收益肉眼可见。

> <strong>小提醒：</strong>燕麦虽好，也不能替代主食的全部；合并糖尿病者注意总量与血糖监测。本文为饮食科普，具体膳食方案请结合个人健康状况。

更多护心食材与烹饪方式红黑榜，欢迎回到科普主页 [「护心厨房」](../index.html#kitchen) 板块查阅。

延伸阅读 · 权威信息来源`
  },

  {
    slug: "weekly-steamed-bass",
    title: "清蒸鲈鱼",
    date: "2026-10-16",
    tags: ["每周一菜"],
    author: "孟自力",
    summary: "想吃肉又怕血脂高？鱼，尤其是深海鱼，是心血管患者更优的蛋白选择。清蒸，则把\"护心\"和\"好吃\"都留下了。",
    body: `## 为什么推荐它？

鱼类（特别是三文鱼、鲭鱼、鲈鱼等）富含 <strong>ω-3 多不饱和脂肪酸（DHA/EPA）</strong>，有助降低甘油三酯、轻度抗炎，对心血管有益。相比红肉与油炸，鱼肉饱和脂肪更低。清蒸的做法几乎不额外加油加盐，把健康价值最大化。

### 食材（2 人份）

- 鲈鱼 1 条（约 400–500 克，也可用其他鲜鱼）
- 姜丝、葱段、蒸鱼豉油（少量）、料酒几滴

### 做法

1. 鱼洗净，两面划几刀，铺姜丝葱段，淋少许料酒去腥；
2. 水开后上锅<strong>大火蒸 8–10 分钟</strong>（按鱼大小调整）；
3. 出锅倒掉盘中水，铺新葱丝，淋少量蒸鱼豉油即可（盐已足够，不必再加）。

## 护心点评

优质蛋白 + ω-3 + 极低额外油脂，是替代红烧肉、油炸鱼的理想一餐。建议每周吃 2 次鱼，其中一次优选富含 ω-3 的鱼种。

> <strong>小提醒：</strong>痛风急性发作期、肾功能不全者请遵医嘱控制蛋白质总量与鱼的种类；蒸鱼豉油含盐，需计入每日盐预算（<5 克/天）。本文为饮食科普，具体请结合个人健康状况。

更多护心食谱，欢迎回到科普主页 [「护心厨房」](../index.html#kitchen) 板块查阅。

延伸阅读 · 权威信息来源`
  }
